using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"NotifTest_{Guid.NewGuid()}")
                .Options;
            _context = new SchoolContext(options);
            _controller = new NotificationsController(_context);

            // Drain the static queue to ensure clean state
            DrainQueue();
        }

        public void Dispose()
        {
            DrainQueue();
            _context.Database.EnsureDeleted();
            _context.Dispose();
            _controller.Dispose();
        }

        private void DrainQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        [Fact]
        public void GetNotifications_ReturnsUpTo10()
        {
            // Arrange - put 15 notifications in the queue
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Test", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            // Use reflection to get 'count' property
            var countProp = jsonValue.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(jsonValue);
            Assert.Equal(10, count);

            svc.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsEmptyList()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            var countProp = jsonValue.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(jsonValue);
            Assert.Equal(0, count);

            var successProp = jsonValue.GetType().GetProperty("success");
            var success = (bool)successProp.GetValue(jsonValue);
            Assert.True(success);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            var successProp = jsonValue.GetType().GetProperty("success");
            var success = (bool)successProp.GetValue(jsonValue);
            Assert.True(success);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void GetNotifications_ReturnsNotificationsWithCorrectData()
        {
            // Arrange
            var svc = new NotificationService();
            svc.SendNotification("Student", "42", "Jane Doe", EntityOperation.CREATE, "admin");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var jsonValue = result.Value;
            var notifProp = jsonValue.GetType().GetProperty("notifications");
            var notifications = notifProp.GetValue(jsonValue) as System.Collections.Generic.List<Notification>;
            Assert.NotNull(notifications);
            Assert.Single(notifications);
            Assert.Equal("Student", notifications[0].EntityType);
            Assert.Equal("42", notifications[0].EntityId);
            Assert.Contains("Jane Doe", notifications[0].Message);

            svc.Dispose();
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Reflection;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            // Clear the static queue before each test
            DrainQueue();
            _service = new NotificationService();
        }

        public void Dispose()
        {
            DrainQueue();
            _service.Dispose();
        }

        private void DrainQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CorrectMessageFormat()
        {
            // Arrange & Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_FallsBackToIdBasedMessage()
        {
            // Arrange & Act
            _service.SendNotification("Course", "101", EntityOperation.UPDATE, "teacher");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 101) has been updated", notification.Message);
            Assert.Equal("teacher", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _service.SendNotification("Department", "5", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_DequeuesInOrder()
        {
            // Arrange
            _service.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            _service.SendNotification("Student", "2", "Second", EntityOperation.UPDATE);
            _service.SendNotification("Student", "3", "Third", EntityOperation.DELETE);

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.Contains("First", first.Message);
            Assert.Equal("CREATE", first.Operation);

            var second = _service.ReceiveNotification();
            Assert.Contains("Second", second.Message);
            Assert.Equal("UPDATE", second.Operation);

            var third = _service.ReceiveNotification();
            Assert.Contains("Third", third.Message);
            Assert.Equal("DELETE", third.Operation);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _service.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void MaxQueueCap_IsEnforced_OldestDiscarded()
        {
            // Arrange - enqueue more than 500 items
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act - count remaining items
            int count = 0;
            while (_service.ReceiveNotification() != null)
            {
                count++;
            }

            // Assert - should be at most 500 (the max cap)
            Assert.True(count <= 500, $"Queue should have at most 500 items but had {count}");
        }

        [Fact]
        public void GenerateMessage_CreateOperation_CorrectFormat()
        {
            // Act
            _service.SendNotification("Course", "101", "Math 101", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("New Course 'Math 101' has been created", notification.Message);
        }

        [Fact]
        public void GenerateMessage_UpdateOperation_CorrectFormat()
        {
            // Act
            _service.SendNotification("Course", "101", "Math 101", EntityOperation.UPDATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
        }

        [Fact]
        public void GenerateMessage_DeleteOperation_CorrectFormat()
        {
            // Act
            _service.SendNotification("Department", "5", "Science", EntityOperation.DELETE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.Equal("Department 'Science' has been deleted", notification.Message);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Arrange
            var service = new NotificationService();

            // Act & Assert
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_CorrectPageItems_TotalPages_HasPreviousPage_HasNextPage()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.True(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Page1_OfMultiPage_HasPreviousPageFalse_HasNextPageTrue()
        {
            // Arrange
            var source = Enumerable.Range(1, 30).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result[0]);
        }

        [Fact]
        public void LastPage_HasNextPageFalse()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.True(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
            Assert.Equal(5, result.Count); // last page has 5 items
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void SinglePage_HasPreviousPageFalse_HasNextPageFalse()
        {
            // Arrange
            var source = Enumerable.Range(1, 5).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
            Assert.Equal(5, result.Count);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_ExactlyOnePage_HasNextPageFalse()
        {
            // Arrange
            var source = Enumerable.Range(1, 10).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }
    }
}

