        public void DeleteConfirmed_Exception_SetsTempDataErrorAndRedirects()
        {
            // Arrange - try to delete non-existent student (will throw NRE on Find(999))
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"StudentsDeleteErr_{Guid.NewGuid()}")
                .Options;
            var context = new SchoolContext(options);
            var controller = new StudentsController(context);
            controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new SessionStateTempDataProvider(new SessionStateSessionStore()));

            // Act - student doesn't exist, will throw
            var result = controller.DeleteConfirmed(999) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.NotNull(controller.TempData["ErrorMessage"]);
            Assert.Contains("Unable to delete", controller.TempData["ErrorMessage"].ToString());

            context.Dispose();
            controller.Dispose();
        }
    }

    // Simple TempData provider for testing
    internal class SessionStateTempDataProvider : ITempDataProvider
    {
        private readonly SessionStateSessionStore _store;

        public SessionStateTempDataProvider(SessionStateSessionStore store)
        {
            _store = store;
        }

        public IDictionary<string, object> LoadTempData(HttpContext context)
        {
            return _store.Data;
        }

        public void SaveTempData(HttpContext context, IDictionary<string, object> values)
        {
            _store.Data = values as Dictionary<string, object> ?? new Dictionary<string, object>(values);
        }
    }

    internal class SessionStateSessionStore
    {
        public Dictionary<string, object> Data { get; set; } = new Dictionary<string, object>();
    }
}

